 54:   if (status === "connected") return "positive";
 55:   if (status === "degraded" || status === "delayed") return "warning";
 56:   if (status === "failed" || status === "disconnected") return "critical";
 57:   return "neutral";
 58: }
 59: 
 60: function sourceStatus(status: string): string {
 61:   if (status === "connected") return "在线";
 62:   if (status === "degraded") return "部分降级";
 63:   if (status === "delayed") return "同步延迟";
 64:   if (status === "failed") return "连接失败";
 65:   if (status === "disconnected") return "未连接";
 66:   return status;
 67: }
 68: 
 69: export function DataSourcesPage() {
 70:   const [overview, setOverview] = useState<EnterpriseTwinOverview | null>(null);
 71:   const [loading, setLoading] = useState(true);
 72:   const [error, setError] = useState<string | null>(null);
 73:   const [syncingSourceKey, setSyncingSourceKey] = useState<string | null>(null);
 74:   const [volumeProfile, setVolumeProfile] = useState<SyncVolumeProfile>("large");
 75: 
 76:   const loadOverview = useCallback(async () => {
 77:     setError(null);
 78:     const response = await apiFetch(`${API_BASE_URL}/api/v1/data-center/overview`, { cache: "no-store" });
 79:     if (!response.ok) throw new Error(await apiErrorMessage(response, "数据中心接口不可用"));
 80:     setOverview((await response.json()) as EnterpriseTwinOverview);
 81:   }, []);
 82: 
 83:   useEffect(() => {
 84:     loadOverview()
 85:       .catch((reason: unknown) => setError(reason instanceof Error ? reason.message : "无法读取数据中心"))
 86:       .finally(() => setLoading(false));
 87:   }, [loadOverview]);
 88: 
 89:   const connectedSources = useMemo(
 90:     () => overview?.sources.filter((source) => source.status === "connected").length ?? 0,
 91:     [overview]
 92:   );
 93: 
 94:   const runSync = useCallback(async (sourceKey: string) => {
 95:     setError(null);
 96:     setSyncingSourceKey(sourceKey);
 97:     try {
 98:       const response = await apiFetch(
 99:         `${API_BASE_URL}/api/v1/data-center/sources/${encodeURIComponent(sourceKey)}/sync`,
100:         {
101:           method: "POST",
102:           headers: { "Content-Type": "application/json" },
103:           body: JSON.stringify({ scenario: "normal", volume_profile: volumeProfile })
104:         }
105:       );
106:       if (!response.ok) throw new Error(await apiErrorMessage(response, "连接器同步失败"));
107:       const payload = (await response.json()) as { overview: EnterpriseTwinOverview };
108:       setOverview(payload.overview);
109:     } catch (reason: unknown) {
110:       setError(reason instanceof Error ? reason.message : "连接器同步失败");
111:     } finally {
112:       setSyncingSourceKey(null);
113:     }
114:   }, [volumeProfile]);
115: 
116:   if (loading) {
117:     return (
118:       <div className="data-source-state" aria-live="polite">
119:         <Database className="spinning" aria-hidden="true" size={28} />
120:         <strong>正在汇总数据接入运行状态</strong>
121:         <span>读取来源注册、同步批次、映射版本和数据库资产</span>
122:       </div>
123:     );
124:   }
125: 
126:   if (!overview) {
127:     return (
128:       <div className="data-source-state failed" role="alert">
129:         <AlertTriangle aria-hidden="true" size={30} />
130:         <strong>数据源运行页暂不可用</strong>
131:         <span>{error}</span>
132:         <button className="button secondary" onClick={() => window.location.reload()} type="button">重新连接</button>
133:       </div>
134:     );
135:   }
136: 
137:   const latestSync = overview.latest_sync;
138:   const latestSource = [...overview.sources]
139:     .filter((source) => source.last_sync_at)
140:     .sort((left, right) => Date.parse(right.last_sync_at ?? "") - Date.parse(left.last_sync_at ?? ""))[0];
141:   const readinessSeries = buildDataReadinessSeries(overview);
142:   const stats = [
143:     { icon: Link2, label: "已注册来源", value: formatCount(overview.sources.length), unit: "个", note: `${connectedSources} 个在线` },
144:     { icon: Rows3, label: "原始记录", value: formatCount(overview.source_record_count), unit: "条", note: "数据库当前存量" },
145:     { icon: Waypoints, label: "统一实体", value: formatCount(overview.entity_count), unit: "个", note: "完成标准化映射" },
146:     { icon: Activity, label: "经营指标", value: formatCount(overview.metrics.length), unit: "个", note: "最新口径快照" },
147:     { icon: Braces, label: "映射版本", value: formatCount(new Set(overview.sources.map((source) => source.mapping_version)).size), unit: "版", note: "按来源独立演进" },
148:     { icon: ServerCog, label: "最近写入", value: formatCount(latestSync?.records_written ?? 0), unit: "条", note: latestSync?.status ?? "尚无批次" }
149:   ];
150: 
151:   return (
152:     <div className="data-source-page">
153:       <PageHeader
154:         actions={
155:           <div className="data-source-actions">
156:             <label>
157:               <span>同步规模</span>
158:               <select
159:                 aria-label="选择同步数据规模"
160:                 disabled={syncingSourceKey !== null}
161:                 onChange={(event) => setVolumeProfile(event.target.value as SyncVolumeProfile)}
162:                 value={volumeProfile}
163:               >
164:                 <option value="small">小型</option>
165:                 <option value="standard">标准</option>
166:                 <option value="large">大型</option>
167:               </select>
168:             </label>
169:             <button
170:               className="button secondary"
171:               onClick={() => void loadOverview().catch((reason: unknown) => setError(reason instanceof Error ? reason.message : "刷新失败"))}
172:               type="button"
173:             >
174:               <RefreshCw aria-hidden="true" size={16} />
175:               刷新运行状态
176:             </button>
177:           </div>
178:         }
179:         description="统一管理来源注册、数据契约、映射版本、同步健康度和可用数据时间。"
180:         eyebrow="DATA FOUNDATION · DATABASE VIEW"
181:         meta={`schema ${overview.schema_version}`}
182:         title="数据源与接入运行"
183:       />
184: 
185:       {error ? <div className="data-source-error" role="alert"><AlertTriangle size={15} />{error}</div> : null}
186: 
187:       <section className="data-source-stat-grid" aria-label="数据接入统计">
188:         {stats.map((stat) => {
189:           const Icon = stat.icon;
190:           return (
191:             <article key={stat.label}>
192:               <span><Icon aria-hidden="true" size={17} />{stat.label}</span>
193:               <strong>{stat.value}<small>{stat.unit}</small></strong>
194:               <p>{stat.note}</p>
195:             </article>
196:           );
197:         })}
198:       </section>
199: 
200:       <div className="data-source-layout">
201:         <section className="data-source-panel source-registry-panel">
202:           <header><div><span>SOURCE REGISTRY</span><h2>来源注册与健康状态</h2></div><em>{connectedSources}/{overview.sources.length} 在线</em></header>
203:           <div className="table-wrap">
204:             <table>
205:               <thead><tr><th>来源</th><th>系统类型</th><th>数据契约</th><th>映射版本</th><th>原始记录</th><th>最后同步</th><th>运行状态</th><th>连接器运行</th></tr></thead>
206:               <tbody>
207:                 {overview.sources.map((source) => (
208:                   <tr key={source.key}>
209:                     <td><strong className="source-name"><span />{source.name}</strong><code>{source.key} · {source.sync_run_count} 批</code></td>
210:                     <td>{source.system_type}</td>
211:                     <td>{source.source_schema_version}</td>
212:                     <td>{source.mapping_version}</td>
213:                     <td><strong>{formatCount(source.source_record_count)}</strong> 条</td>
214:                     <td>{formatTime(source.last_sync_at)}</td>
215:                     <td><StatusBadge value={{ label: sourceStatus(source.status), tone: sourceTone(source.status) }} /></td>
216:                     <td>
217:                       <button
218:                         aria-label={`同步${source.name}`}
219:                         className="source-sync-button"
220:                         disabled={syncingSourceKey !== null}
221:                         onClick={() => void runSync(source.key)}
222:                         title={`按${volumeProfile}规模运行${source.name}同步`}
223:                         type="button"
224:                       >
225:                         {syncingSourceKey === source.key
226:                           ? <LoaderCircle className="spinning" aria-hidden="true" size={14} />
227:                           : <Play aria-hidden="true" size={14} />}
228:                         {syncingSourceKey === source.key ? "同步中" : "运行"}
229:                       </button>
230:                     </td>
231:                   </tr>
232:                 ))}
233:               </tbody>
234:             </table>
235:           </div>
236:           <footer><Database aria-hidden="true" size={14} />{overview.database.engine.toUpperCase()} · {overview.database.persistent ? "持久化运行" : "临时运行"} · 修订 {overview.database.schema_revision}</footer>
